export function parseCsv(text) {
  const rows = [];
  const lines = text.trim().split(/\r?\n/);
  let currentRow = [];
  let inQuote = false;
  let currentField = '';
  for (const line of lines) {
    if (line.trim() === '') {
      if (inQuote) {
        throw new Error('Unclosed quote');
      }
      if (currentRow.length > 0) {
        rows.push(currentRow);
        currentRow = [];
      }
    } else {
      let i = 0;
      while (i < line.length) {
        if (line[i] === '"') {
          if (inQuote) {
            if (line[i + 1] === '"') {
              currentField += '"';
              i += 2;
            } else {
              inQuote = false;
              currentField += line[i];
              i++;
            }
          } else {
            inQuote = true;
            currentField += line[i];
            i++;
          }
        } else if (line[i] === ',' || line[i] === '\r') {
          if (inQuote) {
            currentField += line[i];
          } else {
            currentRow.push(currentField.trim());
            currentField = '';
          }
          i++;
        } else {
          currentField += line[i];
          i++;
        }
      }
      if (inQuote) {
        throw new Error('Unclosed quote');
      }
      currentRow.push(currentField.trim());
    }
  }
  if (inQuote) {
    throw new Error('Unclosed quote');
  }
  if (currentRow.length > 0) {
    rows.push(currentRow);
  }
  return rows;
}
