export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }
  const tokens = [];
  let currentToken = '';
  for (const char of text) {
    if (char.match(/[0-9.+\-*/^ ()]/)) {
      currentToken += char;
    } else if (char === ' ') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
    } else {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
      switch (char) {
        case '+':
        case '-':
        case '*':
        case '/':
        case '^':
          tokens.push(char);
          break;
        default:
          throw new SyntaxError('Unknown character');
      }
    }
  }
  if (currentToken !== '') {
    tokens.push(currentToken);
  }
  if (tokens.length === 0) {
    throw new SyntaxError('Empty input');
  }
  const stack = [];
  const operators = {
    '+': (a, b) => a + b,
    '-': (a, b) => a - b,
    '*': (a, b) => a * b,
    '/': (a, b) => b === 0 ? Infinity : a / b,
    '^': (a, b) => Math.pow(a, b),
  };
  for (const token of tokens) {
    if (token.match(/[0-9.]/)) {
      stack.push(parseFloat(token));
    } else if (token === '(') {
      stack.push(token);
    } else if (token === ')') {
      while (stack[stack.length - 1] !== '(') {
        const op = stack.pop();
        const b = stack.pop();
        const a = stack.pop();
        stack.push(operators[op](a, b));
      }
      stack.pop();
    } else if (token === '-') {
      if (stack.length === 0 || stack[stack.length - 1] === '(') {
        stack.push(-1);
      } else {
        const a = stack.pop();
        stack.push(-a);
      }
    } else {
      while (stack.length > 0 && stack[stack.length - 1] !== '(' && getPrecedence(stack[stack.length - 1]) >= getPrecedence(token)) {
        const op = stack.pop();
        const b = stack.pop();
        const a = stack.pop();
        stack.push(operators[op](a, b));
      }
      stack.push(token);
    }
  }
  while (stack.length > 0) {
    const op = stack.pop();
    const b = stack.pop();
    const a = stack.pop();
    stack.push(operators[op](a, b));
  }
  return stack[0];
}

function getPrecedence(op) {
  switch (op) {
    case '+':
    case '-':
      return 1;
    case '*':
    case '/':
      return 2;
    case '^':
      return 3;
    default:
      return 0;
  }
}
