export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const tokens = text.replace(/\s+/g, ' ').split(' ');
  const stack = [];
  const operators = {
    '+': (a, b) => a + b,
    '-': (a, b) => a - b,
    '*': (a, b) => a * b,
    '/': (a, b) => a / b,
    '^': (a, b) => Math.pow(a, b),
  };

  for (const token of tokens) {
    if (!isNaN(parseFloat(token))) {
      stack.push(parseFloat(token));
    } else if (token in operators) {
      if (stack.length < 2) {
        throw new SyntaxError('Not enough operands for operator');
      }
      const b = stack.pop();
      const a = stack.pop();
      const result = operators[token](a, b);
      stack.push(result);
    } else if (token === '(') {
      stack.push(token);
    } else if (token === ')') {
      if (stack[stack.length - 1] !== '(') {
        throw new SyntaxError('Unbalanced parentheses');
      }
      stack.pop();
    } else {
      throw new SyntaxError('Invalid token: ' + token);
    }
  }

  if (stack.length !== 1) {
    throw new SyntaxError('Not a single value');
  }

  return stack[0];
}
