export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('Both base and userPath must be strings');
  }

  const baseDir = new URL(base).pathname;
  const userPathParts = userPath.split(/\/|\\/);
  const stack = [];

  for (const part of userPathParts) {
    if (part === '..') {
      if (stack.length === 0 || stack[stack.length - 1] === '..') {
        throw new Error('Invalid path');
      }
      stack.pop();
    } else if (part === '' || part === '.') {
      continue;
    } else if (part === '') {
      throw new Error('Invalid path');
    } else if (part.includes('%') || part.includes('\x00')) {
      throw new Error('Invalid path');
    } else {
      stack.push(part);
    }
  }

  const path = stack.join('/');
  if (path.startsWith(baseDir)) {
    return path;
  } else {
    throw new Error('Path out of base');
  }
}
