export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const precedence = {
    '^': 3,
    '*': 2,
    '/': 2,
    '+': 1,
    '-': 1,
  };

  const tokens = [];
  let currentToken = '';
  for (const char of text) {
    if (char === ' ' || char === '\n' || char === '\r') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
    } else if (char === '(' || char === ')') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else if (char === '+' || char === '-' || char === '*' || char === '/' || char === '^') {
      if (currentToken !== '') {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else if (char === '-' && currentToken === '') {
      tokens.push(char);
    } else {
      currentToken += char;
    }
  }
  if (currentToken !== '') {
    tokens.push(currentToken);
  }

  const outputQueue = [];
  const operatorStack = [];

  for (const token of tokens) {
    if (typeof token === 'string' && !isNaN(parseFloat(token))) {
      outputQueue.push(parseFloat(token));
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else if (precedence[token] !== undefined) {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];
  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else if (token === '^') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(Math.pow(left, right));
    } else if (token === '*') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left * right);
    } else if (token === '/') {
      const right = stack.pop();
      const left = stack.pop();
      if (right === 0) {
        throw new RangeError('Division by zero');
      }
      stack.push(left / right);
    } else if (token === '+') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left + right);
    } else if (token === '-') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left - right);
    }
  }

  if (stack.length !== 1) {
    throw new SyntaxError('Invalid expression');
  }

  return stack[0];
}
