export function safeJoinPath(base, userPath) {
  if (typeof base !== 'string' || typeof userPath !== 'string') {
    throw new TypeError('base and userPath must be strings');
  }

  if (base.startsWith('/') && !base.endsWith('/')) {
    throw new Error('base must be an absolute path with a trailing slash');
  }

  const baseParts = base.split('/');
  const userParts = userPath.split('/');

  const normalizedBase = baseParts.filter(part => part !== '').join('/');

  const result = [];
  for (const part of userParts) {
    if (part === '..') {
      if (result.length === 0 || result[result.length - 1] !== normalizedBase) {
        throw new Error('attempt to climb above base');
      }
      result.pop();
    } else if (part === '.') {
      continue;
    } else if (part === '') {
      continue;
    } else if (part === '\\') {
      throw new Error('backslash used as separator');
    } else if (part.includes('%') || part.includes('\x00')) {
      throw new Error('percent-encoded or NUL bytes');
    } else {
      result.push(part);
    }
  }

  return normalizedBase + '/' + result.join('/');
}
