export function parseDuration(text) {
  const parts = text.match(/\d+(?:\.\d+)?[dhms]*/g);
  if (!parts) {
    throw new Error('Invalid duration text');
  }
  const seconds = parts.reduce((acc, part) => {
    const match = part.match(/^(\d+(?:\.\d+)?)([dhms])$/);
    if (!match) {
      throw new Error(`Unknown unit: ${part}`);
    }
    const value = parseFloat(match[1]);
    switch (match[2]) {
      case 'd':
        return acc + value * 24 * 60 * 60;
      case 'h':
        return acc + value * 60 * 60;
      case 'm':
        return acc + value * 60;
      case 's':
        return acc + value;
      default:
        throw new Error(`Unknown unit: ${part}`);
    }
  }, 0);
  return seconds;
}
