export function parseDuration(text) {
  const parts = text.match(/\d+(?:\.\d+)?[dhms]*/g);
  if (!parts) {
    throw new Error('Invalid duration');
  }
  let total = 0;
  for (const part of parts) {
    const match = part.match(/^(\d+(?:\.\d+)?)([dhms])$/);
    if (!match) {
      throw new Error(`Unknown unit: ${part}`);
    }
    const value = parseFloat(match[1]);
    const unit = match[2].toLowerCase();
    switch (unit) {
      case 'd':
        total += value * 24 * 60 * 60;
        break;
      case 'h':
        total += value * 60 * 60;
        break;
      case 'm':
        total += value * 60;
        break;
      case 's':
        total += value;
        break;
      default:
        throw new Error(`Unknown unit: ${unit}`);
    }
  }
  return total;
}
