export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const tokens = text.match(/(\d+(?:\.\d+)?|\+|-|\*|\/|\^|\(|\))/g);
  if (!tokens) {
    throw new SyntaxError('Invalid input');
  }

  const operatorStack = [];
  const operandStack = [];

  for (const token of tokens) {
    if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        const op = operatorStack.pop();
        const operand2 = operandStack.pop();
        const operand1 = operandStack.pop();
        let result;
        switch (op) {
          case '+':
            result = operand1 + operand2;
            break;
          case '-':
            result = operand1 - operand2;
            break;
          case '*':
            result = operand1 * operand2;
            break;
          case '/':
            if (operand2 === 0) {
              throw new RangeError('Division by zero');
            }
            result = operand1 / operand2;
            break;
          case '^':
            result = Math.pow(operand1, operand2);
            break;
        }
        operandStack.push(result);
      }
      operatorStack.pop(); // Remove the '('
    } else {
      if (token === '+' || token === '-' || token === '*' || token === '/' || token === '^') {
        while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && getPrecedence(operatorStack[operatorStack.length - 1]) >= getPrecedence(token)) {
          const op = operatorStack.pop();
          const operand2 = operandStack.pop();
          const operand1 = operandStack.pop();
          let result;
          switch (op) {
            case '+':
              result = operand1 + operand2;
              break;
            case '-':
              result = operand1 - operand2;
              break;
            case '*':
              result = operand1 * operand2;
              break;
            case '/':
              if (operand2 === 0) {
                throw new RangeError('Division by zero');
              }
              result = operand1 / operand2;
              break;
            case '^':
              result = Math.pow(operand1, operand2);
              break;
          }
          operandStack.push(result);
        }
        operatorStack.push(token);
      } else {
        operandStack.push(parseFloat(token));
      }
    }
  }

  while (operatorStack.length > 0) {
    const op = operatorStack.pop();
    const operand2 = operandStack.pop();
    const operand1 = operandStack.pop();
    let result;
    switch (op) {
      case '+':
        result = operand1 + operand2;
        break;
      case '-':
        result = operand1 - operand2;
        break;
      case '*':
        result = operand1 * operand2;
        break;
      case '/':
        if (operand2 === 0) {
          throw new RangeError('Division by zero');
        }
        result = operand1 / operand2;
        break;
      case '^':
        result = Math.pow(operand1, operand2);
        break;
    }
    operandStack.push(result);
  }

  if (operandStack.length !== 1) {
    throw new SyntaxError('Unbalanced parentheses');
  }

  return operandStack[0];
}

function getPrecedence(op) {
  switch (op) {
    case '+':
    case '-':
      return 1;
    case '*':
    case '/':
      return 2;
    case '^':
      return 3;
    default:
      return 0;
  }
}
