export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const precedence = {
    '^': 3,
    '*': 2,
    '/': 2,
    '+': 1,
    '-': 1,
  };

  const tokens = [];
  let currentToken = '';
  let inQuote = false;

  for (const char of text) {
    if (char === '"') {
      inQuote = !inQuote;
    } else if (char === ' ' && !inQuote) {
      if (currentToken) {
        tokens.push(currentToken);
        currentToken = '';
      }
    } else if (char.match(/[+\-*/^()]/)) {
      if (currentToken) {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else {
      currentToken += char;
    }
  }

  if (currentToken) {
    tokens.push(currentToken);
  }

  const operatorStack = [];
  const outputQueue = [];

  for (const token of tokens) {
    if (typeof token === 'string' && token.match(/^\d+(\.\d+)?$/)) {
      outputQueue.push(parseFloat(token));
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else if (token in precedence) {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];

  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      if (token === '+') {
        stack.push(a + b);
      } else if (token === '-') {
        stack.push(a - b);
      } else if (token === '*') {
        stack.push(a * b);
      } else if (token === '/') {
        if (b === 0) {
          throw new RangeError('Division by zero');
        }
        stack.push(a / b);
      } else if (token === '^') {
        stack.push(Math.pow(a, b));
