  let currentToken = '';
  for (const char of text) {
    if (char.match(/[0-9.]/)) {
      currentToken += char;
    } else if (char.match(/[-+*/^ ()]/)) {
      if (currentToken) {
        tokens.push(currentToken);
        currentToken = '';
      }
      tokens.push(char);
    } else if (char === ' ') {
