        tokens.push(currentToken);
        currentToken = '';
      }
    } else {
      throw new SyntaxError(`Invalid character: ${char}`);
    }
  }
  if (currentToken) {
    tokens.push(currentToken);
  }

  const outputQueue = [];
  const operatorStack = [];

  for (const token of tokens) {
    if (token.match(/[0-9.]/)) {
      outputQueue.push(parseFloat(token));
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else if (token in precedence) {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    } else {
      throw new SyntaxError(`Invalid token: ${token}`);
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];
  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else if (token === '^') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(Math.pow(left, right));
    } else if (token === '*') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left * right);
    } else if (token === '/') {
      const right = stack.pop();
      const left = stack.pop();
      if (right === 0) {
        throw new RangeError('Division by zero');
      }
      stack.push(left / right);
    } else if (token === '+') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left + right);
    } else if (token === '-') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left - right);
    }
  }

