export function evalArithmetic(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  const tokens = text.match(/(\d+(?:\.\d+)?|\^|\+|-|\*|\/|\(|\)|\s)/g);
  if (tokens.length === 0) throw new SyntaxError('Empty input');
  const stack = [];
  const operatorStack = [];
  for (const token of tokens) {
    if (token === ' ') continue;
    if (token === '(') operatorStack.push(token);
    else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        const op = operatorStack.pop();
        const b = stack.pop();
        const a = stack.pop();
        if (op === '^') stack.push(Math.pow(a, b));
        else if (op === '+') stack.push(a + b);
        else if (op === '-') stack.push(a - b);
        else if (op === '*') stack.push(a * b);
        else if (op === '/') stack.push(Math.floor(a / b));
      }
      operatorStack.pop();
    } else if (token === '+' || token === '-' || token === '*' || token === '/' || token === '^') {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== '(' && getPrecedence(operatorStack[operatorStack.length - 1]) >= getPrecedence(token)) {
        const op = operatorStack.pop();
        const b = stack.pop();
        const a = stack.pop();
        if (op === '^') stack.push(Math.pow(a, b));
        else if (op === '+') stack.push(a + b);
        else if (op === '-') stack.push(a - b);
        else if (op === '*') stack.push(a * b);
        else if (op === '/') stack.push(Math.floor(a / b));
      }
      operatorStack.push(token);
    } else {
      stack.push(parseFloat(token));
    }
  }
  while (operatorStack.length > 0) {
    const op = operatorStack.pop();
    const b = stack.pop();
    const a = stack.pop();
    if (op === '^') stack.push(Math.pow(a, b));
    else if (op === '+') stack.push(a + b);
    else if (op === '-') stack.push(a - b);
    else if (op === '*') stack.push(a * b);
    else if (op === '/') stack.push(Math.floor(a / b));
  }
  if (stack.length !== 1) throw new SyntaxError('Unbalanced parentheses');
  return stack[0];
}

function getPrecedence(op) {
  if (op === '^') return 3;
  if (op === '*' || op === '/') return 2;
  if (op === '+' || op === '-') return 1;
