export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('Input must be an array');
  }
  const validIntervals = intervals.filter(interval => Array.isArray(interval) && interval.length === 2 && Number.isFinite(interval[0]) && Number.isFinite(interval[1]) && interval[0] <= interval[1]);
  if (validIntervals.some(interval => interval[0] > interval[1])) {
    throw new RangeError('Interval start must not be greater than end');
  }
  if (validIntervals.length === 0) {
    return [];
  }
  validIntervals.sort((a, b) => a[0] - b[0]);
  const merged = [validIntervals[0]];
  for (let i = 1; i < validIntervals.length; i++) {
    const current = validIntervals[i];
    const last = merged[merged.length - 1];
    if (current[0] <= last[1]) {
      merged[merged.length - 1] = [last[0], Math.max(last[1], current[1])];
    } else {
      merged.push(current);
    }
  }
  return merged;
}
