export function parseCsv(text) {
  const lines = text.split(/\r?\n/);
  const result = [];
  let currentRow = [];
  let inQuote = false;
  let currentField = '';

  for (const line of lines) {
    let i = 0;
    while (i < line.length) {
      const char = line[i];
      if (char === '"') {
        inQuote = !inQuote;
        currentField += char;
        i++;
      } else if (char === ',' && !inQuote) {
        currentRow.push(currentField);
        currentField = '';
        i++;
      } else if (char === '\r' || char === '\n') {
        if (inQuote) {
          currentField += char;
        }
        if (currentField.trim() !== '') {
          currentRow.push(currentField);
        }
        result.push(currentRow);
        currentRow = [];
        inQuote = false;
        i++;
      } else {
        currentField += char;
        i++;
      }
    }
    if (currentField.trim() !== '') {
      currentRow.push(currentField);
    }
  }
  if (currentField.trim() !== '') {
    currentRow.push(currentField);
  }
  if (currentRow.length > 0) {
    result.push(currentRow);
  }
  if (inQuote) {
    throw new Error('Unclosed quote');
  }
  return result;
